        cout << "Processing line: " << line << endl;
        data.rows_processed++; // Increment the row count
    }

    file.close(); // Close the file after processing
    return data;
}

// Function to clean and preprocess data (CSV or JSON)
// This function performs data cleaning tasks such as removing special characters
// and converting text to lowercase.
ProcessedData clean_data(const string& file_path) {
    ProcessedData data;
    ifstream file(file_path); // Open the file
    string line;

    if (!file.is_open()) {
        cerr << "Error opening file: " << file_path << endl;
        return data;
    }

    while (getline(file, line)) {
        // Remove special characters and convert to lowercase
        regex special_chars("[^a-zA-Z0-9\\s]"); // Regular expression to match non-alphanumeric characters
        string cleaned_line = regex_replace(line, special_chars, ""); // Replace special characters with an empty string
        cleaned_line = (cleaned_line.size() > 0) ? tolower(cleaned_line[0]) + cleaned_line.substr(1) : ""; // Convert to lowercase

        // Simulate data processing
        data.rows_processed++;
    }

    file.close();
    return data;
}

// Main function
int main() {
    auto start_time = chrono::steady_clock::now(); // Record the start time
    int total_processed = 0; // Initialize total processed rows

    // Iterate through data files in the specified directory
    for (const auto& filename : get_files(DATA_DIR)) { // Get list of files in DATA_DIR
        string file_path = DATA_DIR + "/" + filename; // Construct the full file path
        ProcessedData data = clean_data(file_path);  // Process the data
        total_processed += data.rows_processed;  // Update total processed rows
    }

    auto end_time = chrono::steady_clock::now(); // Record the end time
    auto duration = chrono::duration_cast<chrono::milliseconds>(end_time - start_time); // Calculate the duration

    cout << "Total files processed: " << total_processed << " in " << duration.count() << " milliseconds." << endl;

    // Generate Daily/Weekly Report (Simplified)
    string report_date = chrono::format("%Y-%m-%d", chrono::system_clock::now()); // Get the current date
    string report_file = OUTPUT_DIR + "/" + report_date + ".txt"; // Construct the report file path
    ofstream report_file(report_file); // Open the report file
    if (report_file.is_open()) {
        report_file << "Date: " << report_date << endl; // Write the date to the report
        report_file << "Total Sales: " << total_processed << endl; // Write the total sales to the report
        report_file.close(); // Close the report file
